(function(){
const questions = [
['你的许愿申请被退回了，只能留一个“小愿望”。你选？',['今天买的水果，别再像开盲盒一样难吃。','回家那趟地铁，能有个座就行。','今晚别手欠，发出明早想撤回的消息。','外卖图片里的肉，实物最好也认识我。'],[0,1,2,3]],
['一位小神仙来应聘，你最想看见哪条工作经历？',['曾让一位连续加班的人，在周末自然醒到十一点。','成功安排高冷小猫主动接近人类，并停留七分钟。','连续三次挑中好吃的西瓜，未使用任何仙术外挂。','熟悉全市公共座椅分布，尤其了解哪个有靠背。'],[4,5,0,1]],
['你今天很不顺，神仙说可以补偿一项服务。',['把今晚准备发给某个人的长消息，先转存草稿箱。','让老板说一句：“这个刚好多做了一份，送你。”','帮你取消一个其实不想去的局，对方还先说了抱歉。','让路边小狗越过三个人，精准走到你面前摇尾巴。'],[2,3,4,5]],
['你发现神仙偷偷挪用了三块钱经费，你希望它买的是？',['一块小蛋糕。上面歪歪扭扭地写着“今天也算过关”。','一张按摩椅体验券。时间不长，但这五分钟谁也别找你。','一个手机防水袋。它说：“不是防水，主要防你冲动。”','两根烤肠。你一根，它站在旁边吃一根。'],[0,1,2,3]],
['神仙的保佑失败了，你迟到了。哪种解释最容易让你原谅它？',['“对不起，看你睡得太香，闹钟响的时候我按掉了。”','“路上那只猫今天只营业五分钟，我怕你错过。”','“早餐店刚出炉那一锅最好吃，我让队伍多停了一会儿。”','“我在下一班车上给你占了座，没想到你跑这么快。”'],[4,5,0,1]],
['睡前，神仙在你床头留了一张纸条。你最想看到哪张？',['“有些话明天再发。今晚你说给我听，我不截图。”','“冰箱里还有吃的。我检查过，够你踏踏实实吃一顿。”','“明天可以晚点起，世界不会因为你多睡一会儿停转。”','“今天那只猫不是谁都蹭。你确实被它选中了。”'],[2,3,4,5]]
];
const gods = [
{name:'西瓜包甜仙',icon:'🍉',color:'#dce8c7',budget:'3.50',job:'日常快乐质量抽检员',quote:'大的喜事还在排队，小的甜头先给你尝。',story:['你的神仙以前在天庭负责蟠桃质检，因为偷偷把最甜的留给加班仙，被调到了人间水果摊。','现在主要负责：你随手挑的西瓜刚好很甜，新买的饮料没踩雷，走了一整天后发现街角那家店还亮着灯。','它觉得你这个人很好养，但不能糊弄。日子可以平常，至少吃进嘴里的那一口，要让你觉得“嗯，今天还行”。','别人劝你把眼光放长远，它只盯着你手里的桃子：“长远的事明天再说，这个再放就软了。”'],note:'别总把喜欢的留到最后。水果会坏，蛋糕会塌，快乐也可以今天就拆。',luck:'下一次给自己买点喜欢的，不必先证明今天表现优秀。',card:'我的守护神经费只有三块五。\n但它坚持给我挑最甜的那块。',caption:'查到了，我在天庭的关系主要分布在水果摊。'},
{name:'地铁空座神',icon:'🚇',color:'#d9e6ed',budget:'2.00',job:'人类临时停靠位调度员',quote:'它不保证一路顺风，但想让你坐着吹。',story:['你的神仙腿很短，每天跑得比谁都勤。','你还没进站，它已经上车勘察；你还在说“没关系，我站着就行”，它已经盯上了那个准备下车的人。','它的工作信条是：“站着也能到，但你今天已经够累了。”','按这份答卷，它最想照顾的，是你习惯自己消化的疲惫。很多事你都说能扛，它听完却会在本子上记一笔：此人需要一个有靠背的位置。','它不能替你走完所有路，但愿意提前去找找，哪里可以歇脚。'],note:'有座就坐，有人帮忙就说谢谢。你不需要一路站着，证明自己很能撑。',luck:'今天给自己留十分钟，不赶路，也不顺便处理消息。',card:'别人的神仙保升职。\n我的神仙挤在下一站，给我找座。',caption:'人脉已查明：地铁上那个即将下车的人。'},
{name:'消息防手滑使',icon:'📵',color:'#e5dcef',budget:'0.80',job:'深夜消息风险拦截员',quote:'你的体面，有时是它拼命摁住了发送键。',story:['这位神仙白天很闲，晚上十一点准时上岗。','它见过你输入“在吗”，删除。输入“其实有些话”，删除。最后发了一条看似无事发生、实际希望特定人士看见的动态。','它坐在信号塔上，深深叹气。','它知道，你有时候只是希望自己的话能得到认真回应。可一个迟迟不回的聊天框，很容易让人越写越多。','所以它偶尔会安排网络卡顿、手机没电，或者让你突然发现：算了，这个人甚至不值得我重新组织一遍语言。'],note:'想说的话可以先写下来。等明天再决定，谁值得收到这一份。',luck:'今晚允许自己退出一个反复点开的聊天框，不必发表退场感言。',card:'我在人间深夜 emo。\n我的神仙在信号塔上拔网线。',caption:'建议这位神仙加大工作力度，尤其晚上十一点以后。'},
{name:'外卖加肉神',icon:'🍜',color:'#f4d8bb',budget:'6.00',job:'人间实惠型关怀派送员',quote:'它不太会安慰人，它问你要不要加个蛋。',story:['你的神仙不擅长说漂亮话。','你说今天受委屈了，它低头扒拉口袋。你说最近好像什么都没做好，它开始看附近哪家还营业。你说算了，不讲了。','它把饭往你面前推了推：“可以不讲。趁热吃。”','这份答卷里，你偏爱的照顾都挺具体：有人记得你的口味，愿意多留一份，知道你说“随便”时其实已经很累。','所以办事处给你分配了这位行动派。它的情话库存几乎为零，加料手倒是一直很稳。'],note:'今天过得怎么样，都不影响你值得好好吃饭。',luck:'下一顿坐下来吃。喜欢什么，就认真给自己点一份。',card:'我的守护神不会画饼。\n它只会往饼里多夹两块肉。',caption:'查到了，我的福报是可食用的。'},
{name:'被窝续时仙',icon:'💤',color:'#e3def1',budget:'1.20',job:'非必要营业暂停管理员',quote:'你的宏图大业，它建议睡醒再议。',story:['你的神仙上任第一天，就把“随时待命”从你的灵魂合同里划掉了。','它最常处理的业务包括：不想去的饭局刚好取消，周末的消息写着“不急”，闹钟响前发现今天放假。','它曾因工作态度散漫被天庭约谈。领导问：“为什么你的服务对象最近没什么大动作？”','它说：“翻身了。睡得挺好。”','你选中的，是不被催促的时间。能按自己的节奏过一会儿，不用马上回应，也不用把休息变成另一项任务。对此，它非常支持，甚至已经替你掖好了被角。'],note:'空出来的时间可以一直空着。不必急着拿另一个任务填进去。',luck:'挑一个不影响正事的小空档，理直气壮地歇一会儿。',card:'我的守护神已替我婉拒：\n不必要的局、过量的活、凌晨的自我审判。',caption:'查到了，我在天庭有人替我请假。'},
{name:'路边猫缘神',icon:'🐈',color:'#f3dfae',budget:'4.00',job:'跨物种偏爱临时安排员',quote:'它想让你知道，你也是会被主动靠近的人。',story:['这位神仙性格腼腆，不敢直接告诉你“今天辛苦了”。','于是它会去跟路边的猫商量：“看见那个人了吗？过去蹭一下。”猫说不去。它加一根猫条。猫说最多三分钟，不能摸肚子。','你蹲下来，以为今天猫缘不错。它躲在树后，盯着秒表，生怕甲方提前下班。','你的选择里，最打动人的照顾常常没有太多解释：有人主动找你，一个小动物放心靠近，一点不用争取的亲近。'],note:'被喜欢的时候，可以先高兴一会儿，不必马上研究自己哪里值得。',luck:'留意一次善意，并允许自己相信：这确实是给你的。',card:'今天有猫主动蹭我。\n后台查了，是我的神仙自费买的猫条。',caption:'原来我在人间被小动物喜欢，是上面打过招呼了。'}
];
function score(answers){if(answers.length!==6||answers.some(a=>!Number.isInteger(a)||a<0||a>3))throw Error('请完成六道题');const votes=answers.map((a,i)=>questions[i][2][a]);const counts=Array(6).fill(0);votes.forEach(v=>counts[v]++);const max=Math.max(...counts);return votes.slice().reverse().find(v=>counts[v]===max);}

window.GodsData={questions:questions,gods:gods,score:score};
})();
